            if diff > best_diff:
                best_diff = diff
                best = r
        if best is not None:
            target = best
    tx, ty = target
    best_move = (0, 0)
    best_val = -10**18
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        if blocked(nx, ny):
            continue
        our_d = man((nx, ny), (tx, ty))
        opp_d = man((ox, oy), (tx, ty))
        val = (-our_d, opp_d)
        if val > (best_val, best_val):
            best_val = val[0]
            best_move = (dx, dy)
        elif val[0] == best_val:
            if (dx, dy) == (best_move[0], best_move[1]):
                pass
    if blocked(sx + best_move[0], sy + best_move[1]):
        for dx, dy in moves:
            if not blocked(sx + dx, sy + dy):
                return [int(dx), int(dy)]
    return [int(best_move[0]), int(best_move[1])]

def choose_move(observation):
